import {
  Eye,
  EyeOff,
  FileText,
  Lock,
  Zap,
} from 'lucide-react';

import FormFieldSaveForm from '@/Components/Forms/Backend/Form/Field/FormFieldSaveForm';
import { Badge } from '@/Components/UI/Badge';
import StatusBadge from '@/Components/UI/StatusBadge';
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from '@/Components/UI/Tooltip';
import { useTranslations } from '@/Hooks/useTranslations';
import type { CrudConfig, CrudPageProps } from '@/Types/crud';
import React from 'react';
import z from 'zod';
export function useFormFieldConfig(props: CrudPageProps): CrudConfig {

  const { t } = useTranslations();

  const modelProperty = props?.modelProperty;
  const form = props?.form?.data;

  const formName = form?.name



  const advanceFilterOptions = props?.advanceFilterOptions || [];
  const routePrefix = modelProperty?.routePrefix;

  const formFieldRoutePredix = `${routePrefix}.fields`;

  const baseBreadcrumbs = [
    { label: t('Dashboard'), href: route('backend.dashboard') },
    { label: t('Forms'), href: route(`${routePrefix}.index`) },
    { label: t('Fields'), href: route(`${formFieldRoutePredix}.index`, { form: form?.uuid }) }
  ];

  const inputTypeOptions = props?.inputTypes || [];

  const parentFieldOptions = props?.parentFields?.data?.map((field: any) => ({
    value: field?.id,
    label: field?.label,
    type: field?.input_type
  })) || [];


  const statusOptions = [
    { value: 'active', label: t('Active') },
    { value: 'inactive', label: t('Inactive') },
  ];

  return {
    formComponent: FormFieldSaveForm,
    fetchToggle: false,

    form: {
      title: {
        create: t(`Create Field For ${formName}`),
        edit: t(`Edit Form Field ${formName}`),
      },
      description: {
        create: t(`Add a new field to your ${formName} form`),
        edit: t(`Update  ${formName} form field configuration`),
      },
      submitButtonText: {
        create: t('Create Field'),
        edit: t('Update Field'),
      },

      fields: [

        {
          name: 'name',
          label: t('Field Name'),
          type: 'text',
          placeholder: t('field_name'),
          required: true,
          section: 'basic',
          gridColumn: 'span 1',
          description: t('Unique identifier for this field (lowercase, no spaces)'),
        },
        {
          name: 'label',
          label: t('Field Label'),
          type: 'text',
          placeholder: t('Enter field label'),
          required: true,
          section: 'basic',
          gridColumn: 'span 2',
          description: t('Display label for the field in forms'),
        },
        {
          name: 'order_level',
          label: t('Order level'),
          type: 'number',
          placeholder: t('Enter order level'),
          required: true,
          section: 'basic',
          gridColumn: 'span 1',
          min: 1,
          max: 8000

        },
        {
          name: 'input_type',
          label: t('Input Type'),
          type: 'select',
          placeholder: t('Select input type'),
          required: true,
          section: 'basic',
          gridColumn: 'span 1',
          options: inputTypeOptions,
          description: t('Choose the type of input control'),
        },
        {
          name: 'placeholder',
          label: t('Placeholder Text'),
          type: 'text',
          placeholder: t('Enter placeholder text'),
          required: false,
          section: 'configuration',
          gridColumn: 'span 2',
          description: t('Hint text shown inside the input field'),
        },
        {
          name: 'hint_text',
          label: t('Hint Text'),
          type: 'text',
          placeholder: t('Enter hint text'),
          required: false,
          section: 'configuration',
          gridColumn: 'span 2',
          description: t('Helper text displayed below the field'),
        },
        {
          name: 'description',
          label: t('Description'),
          type: 'textarea',
          placeholder: t('Enter field description'),
          required: false,
          section: 'configuration',
          gridColumn: 'span 3',
          description: t('Additional details about this field'),
          rows: 3,
        },
        {
          name: 'default_value',
          label: t('Default Value'),
          type: 'text',
          placeholder: t('Enter default value'),
          required: false,
          section: 'configuration',
          gridColumn: 'span 2',
          description: t('Value to populate if field is not filled'),
        },
        {
          name: 'values',
          label: t('Field Options'),
          type: 'key-value',
          placeholder: t('Add options'),
          required: false,
          section: 'configuration',
          gridColumn: 'span 3',
          description: t('Define options for select or multi-select  Add key-value pairs where key is the stored value and value is the display label.'),
          conditional: (formData: any) =>
            ['select', 'multi-select'].includes(formData?.input_type),
        },
        // {
        //   name: 'parent_id',
        //   label: t('Parent Field'),
        //   type: 'select',
        //   placeholder: t('Select parent field'),
        //   required: false,
        //   section: 'configuration',
        //   gridColumn: 'span 2',
        //   options: parentFieldOptions,
        //   description: t('Select a select/multi-select field to conditionally display this field based on parent selection'),
        //   conditional: (formData: any) =>
        //     ['select', 'multi-select'].includes(formData?.input_type),
        // },
        {
          name: 'is_required',
          label: t('Is Required'),
          type: 'switch',
          required: false,
          section: 'attributes',
          gridColumn: 'span 1',
          description: t('Make this field mandatory'),
        },
        {
          name: 'is_read_only',
          label: t('Is Read Only'),
          type: 'switch',
          required: false,
          section: 'attributes',
          gridColumn: 'span 1',
          description: t('Prevent field from being edited'),
        },
        {
          name: 'is_hidden',
          label: t('Is Hidden'),
          type: 'switch',
          required: false,
          section: 'attributes',
          gridColumn: 'span 1',
          description: t('Hide field from display'),
        },
        {
          name: 'validation_rules',
          label: t('Validation Rules'),
          type: 'validation-rules',
          placeholder: t('Add validation rules'),
          required: false,
          section: 'validation',
          gridColumn: 'span 3',
          description: t('Define custom validation rules for this field. Rules are type-aware and validated on the backend.'),
        },
        {
          name: 'status',
          label: t('Status'),
          type: 'select',
          placeholder: t('Select status'),
          required: true,
          section: 'status',
          gridColumn: 'span 2',
          options: statusOptions,
          description: t('Field availability status'),
        },
      ],
    },

    formValidationRules: {
      name: z.string('Field name is required').min(1, 'Field name is required').max(191, 'Field name must not exceed 191 characters').regex(/^[a-z0-9_]+$/, 'Field name must be lowercase with underscores only'),
      label: z.string('Label is required').min(1, 'Label is required').max(191, 'Label must not exceed 191 characters'),
      input_type: z.string('Input type is required').min(1, 'Input type must be selected'),
      placeholder: z.string().optional(),
      hint_text: z.string().optional(),
      description: z.string().optional(),
      default_value: z.string().optional(),
      order_level: z.any(),
      values: z.any().optional(),
      parent_id: z.any().optional(),
      is_required: z.boolean().optional(),
      is_read_only: z.boolean().optional(),
      is_hidden: z.boolean().optional(),
      validation_rules: z.any().optional(),
      status: z.string().min(1, 'Status is required'),
    },

    resource: 'form_field',
    resourcePlural: 'form_fields',
    title: t(`${formName} Form Fields`),
    description: t('Manage form fields and their configurations'),

    routes: {
      index: `${formFieldRoutePredix}.index`,
      create: `${formFieldRoutePredix}.create`,
      edit: `${formFieldRoutePredix}.edit`,
      store: `${formFieldRoutePredix}.store`,
      update: `${formFieldRoutePredix}.update`,
      destroy: `${formFieldRoutePredix}.destroy`,
      bulkAction: `${formFieldRoutePredix}.bulk.action`,
      updateStatus: `${formFieldRoutePredix}.update.status`,
    },
    routeParams: {
      index: { form: form?.uuid },
      create: { form: form?.uuid },
      edit: { field: "{item.id}", form: form?.uuid },
      destroy: { field: "{item.id}", form: form?.uuid },

    },

    formDisplayMode: 'page',
    viewDisplayMode: 'page',
    statusType: 'binary',

    breadcrumbs: {
      index: [
        { label: t('Dashboard'), href: route('backend.dashboard') },
        { label: t('Form'), href: route(`${routePrefix}.index`) },
        { label: t('Fields'), href: null },

      ],
      create: [
        ...baseBreadcrumbs,
        { label: t('Create'), href: null, active: true },
      ],
      update: [
        ...baseBreadcrumbs,
        { label: t('Update'), href: null, active: true },
      ],
    },

    table: {
      selectable: true,
      searchable: true,
      serializable: false,
      searchPlaceholder: t('Search fields by name, label...'),
      sortable: true,
      defaultSort: 'created_at',
      defaultSortDirection: 'desc',
      emptyMessage: t('No form fields available. Create your first field to get started.'),
      emptyMessageIcon: FileText,
      dragdrop: true,
      dragdropRoute: `${formFieldRoutePredix}.update.order`,

      bulkActions: [
        { key: 'delete', permission: 'form-field.delete' },
        { key: 'active', permission: 'form-field.edit' },
        { key: 'inactive', permission: 'form-field.edit' },
      ],

      columns: [
        {
          key: 'label',
          label: t('Field Label'),
          sortable: false,
          filterable: true,
          priority: 0,
          render: (row: any) => (
            <div className="space-y-1">
              <div className="text-sm font-medium text-gray-900 dark:text-gray-100">{row.label}</div>
              <div className="text-xs text-gray-500 dark:text-gray-400">{row.name}</div>
            </div>
          ),
        },
        {
          key: 'form',
          label: t('Form'),
          sortable: false,
          filterable: true,
          priority: 1,
          render: (row: any) => <div className="text-sm text-gray-900 dark:text-gray-100">{row.form?.name || '-'}</div>,
        },

        {
          key: 'input_type',
          label: t('Type'),
          sortable: false,
          filterable: true,
          priority: 1,
          render: (row: any) => <Badge variant="secondary" className="text-xs capitalize">{row.input_type.replace(/-/g, ' ')}</Badge>,
        },
        {
          key: 'parent',
          label: t('Parent Field'),
          sortable: false,
          filterable: false,
          priority: 2,
          render: (row: any) => (
            <div className="text-sm text-gray-900 dark:text-gray-100">
              {row.parent?.label ? <span className="inline-flex items-center gap-1">{row.parent.label}</span> : '-'}
            </div>
          ),
        },
        {
          key: 'attributes',
          label: t('Attributes'),
          sortable: false,
          filterable: false,
          priority: 2,
          render: (row: any) => (
            <TooltipProvider>
              <div className="flex gap-1.5">
                {row.is_required && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="inline-flex items-center gap-1 px-2 py-1 text-xs bg-red-100 dark:bg-red-900/20 text-red-700 dark:text-red-300 rounded cursor-help hover:bg-red-200 dark:hover:bg-red-900/30 transition-colors">
                        <Zap className="w-3 h-3" />
                      </span>
                    </TooltipTrigger>
                    <TooltipContent side="bottom" className="text-xs">
                      {t('Required Field')}
                    </TooltipContent>
                  </Tooltip>
                )}

                {row.is_read_only && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="inline-flex items-center gap-1 px-2 py-1 text-xs bg-yellow-100 dark:bg-yellow-900/20 text-yellow-700 dark:text-yellow-300 rounded cursor-help hover:bg-yellow-200 dark:hover:bg-yellow-900/30 transition-colors">
                        <Lock className="w-3 h-3" />
                      </span>
                    </TooltipTrigger>
                    <TooltipContent side="bottom" className="text-xs">
                      {t('Read Only')}
                    </TooltipContent>
                  </Tooltip>
                )}

                {row.is_hidden && (
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="inline-flex items-center gap-1 px-2 py-1 text-xs bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300 rounded cursor-help hover:bg-gray-200 dark:hover:bg-gray-700 transition-colors">
                        <EyeOff className="w-3 h-3" />
                      </span>
                    </TooltipTrigger>
                    <TooltipContent side="bottom" className="text-xs">
                      {t('Hidden Field')}
                    </TooltipContent>
                  </Tooltip>
                )}
              </div>
            </TooltipProvider>
          ),
        },
        {
          key: 'status',
          label: t('Status'),
          sortable: false,
          filterable: false,
          priority: 3,
          render: (row: any) => {

            return (<div className="mt-1.5">

              <StatusBadge status={row.status} />

            </div>);
          },
        },
        {
          key: 'created_at',
          label: t('Created'),
          sortable: false,
          priority: 4,
          renderType: 'date',
        },
      ]
    },

    stats: [
      { key: 'total', title: t('Total Fields'), icon: FileText, iconColor: 'text-blue-600', iconBgColor: 'bg-blue-100 dark:bg-blue-900', description: t('All form fields') },
      { key: 'active', title: t('Active'), icon: Eye, iconColor: 'text-green-600', iconBgColor: 'bg-green-100 dark:bg-green-900', description: t('Active fields') },
      { key: 'inactive', title: t('Inactive'), icon: EyeOff, iconColor: 'text-gray-600', iconBgColor: 'bg-gray-100 dark:bg-gray-900', description: t('Inactive fields') },
      { key: 'required', title: t('Required'), icon: Zap, iconColor: 'text-red-600', iconBgColor: 'bg-red-100 dark:bg-red-900', description: t('Required fields') },
    ],

    filters: {
      searchFields: ['name', 'label', 'description'],
      filterFields: advanceFilterOptions,
    },

    permissions: {
      actions: {
        create: 'form-field.create',
        edit: 'form-field.edit',
        view: 'form-field.view',
        delete: 'form-field.delete',
      },
    },

    destroyDialogConfig: {
      title: t('Delete Form Field'),
      description: t('Are you sure you want to delete this form field?'),
      itemName: {
        label: t('Field Label'),
        key: 'label',
        render: (label: string) => label,
      },
      itemType: 'Form Field',
      warningMessage: t('Deleting this field will remove it from all forms and cannot be undone.'),
      showWarningAlert: true,
      showItemDetails: true,
      itemDisplayFields: [
        { label: t('Label'), key: 'label', className: 'font-semibold text-gray-900 dark:text-gray-100' },
        { label: t('Field Name'), key: 'name', render: (name: string) => React.createElement('code', { className: 'px-2 py-1 text-xs bg-gray-100 rounded dark:bg-gray-800 text-gray-600 dark:text-gray-400' }, name) },
        { label: t('Input Type'), key: 'input_type', render: (type: string) => React.createElement('span', { className: 'inline-flex items-center px-2 py-1 rounded text-xs font-medium bg-blue-100 text-blue-800 dark:bg-blue-900 dark:text-blue-200 capitalize' }, type.replace(/-/g, ' ')) },
        { label: t('Status'), key: 'status', render: (status: string) => React.createElement('span', { className: `inline-flex items-center px-2 py-1 rounded-full text-xs font-medium capitalize ${status === 'active' ? 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200' : 'bg-gray-100 text-gray-800 dark:bg-gray-700 dark:text-gray-200'}` }, status) },
      ],
    },

    labels: {
      singular: formName + ' Form Field',
      plural: formName + ' Form Fields',
    },

    saveAlertInfo: {
      title: t('Form Field Configuration'),
      description: t('Configure your form field settings. For select or multi-select fields, you must define the available options. Add validation rules to ensure data quality.'),
    },
  };
}